import{_ as s,o as r,c as t,a5 as e}from"./chunks/framework.DJo0M80U.js";const c=JSON.parse('{"title":"props","description":"直接用 ...props 生成的新对象，拿到的是“当下快照”，大多数键的 响应性会丢失。 细化说明（不写代码，只讲机制与做法）： 为什么会丢 ：props 是一个受 Vue 代理追踪的只读响应式对象；当你用展开语法创建 新字面量对象 时，拷贝的是 各键当前的值 ，新对象本身不受代。","frontmatter":{"title":"props","date":"2026-08-11T00:00:00.000Z","categories":["Vue 系统教程"],"tags":["Vue","Vue3","前端","教程","OneNote","响应式与组合式 API"],"description":"直接用 ...props 生成的新对象，拿到的是“当下快照”，大多数键的 响应性会丢失。 细化说明（不写代码，只讲机制与做法）： 为什么会丢 ：props 是一个受 Vue 代理追踪的只读响应式对象；当你用展开语法创建 新字面量对象 时，拷贝的是 各键当前的值 ，新对象本身不受代。","sidebarWeight":132,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/f-vue/响应式问题/Prop.属性名传入composable失去响应/..props.md"},"headers":[],"relativePath":"posts/Vue系统教程/03-响应式与组合式 API/Prop.属性名传入composable失去响应/props.md","filePath":"posts/Vue系统教程/03-响应式与组合式 API/Prop.属性名传入composable失去响应/props.md"}'),p={name:"posts/Vue系统教程/03-响应式与组合式 API/Prop.属性名传入composable失去响应/props.md"};function n(l,o,g,i,a,d){return r(),t("div",null,[...o[0]||(o[0]=[e('<div><h1 id="props" tabindex="-1">props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;props&quot;">​</a></h1><blockquote><p>本节目标：理解“props”的核心思路，并能把它用于实际开发或面试表达。 <strong>直接用 ...props 生成的新对象，拿到的是“当下快照”，大多数键的</strong>响应性会丢失。</p></blockquote><p>细化说明（不写代码，只讲机制与做法）：</p><ul><li><strong>为什么会丢</strong>：props 是一个受 Vue 代理追踪的只读响应式对象；当你用展开语法创建<strong>新字面量对象</strong>时，拷贝的是<strong>各键当前的值</strong>，新对象本身不受代理追踪，所以<strong>父级后续改动不会再推动这些键</strong>。</li><li><strong>哪些情况“看似还会动”</strong>： <ul><li>若某个 prop 的值本身是<strong>Ref</strong>，你把它的“值”拷过去就变成普通值了（失去响应）。</li><li>若某个 prop 的值是<strong>对象/数组</strong>，拷贝的是<strong>同一个引用</strong>，对象内部被<strong>就地修改</strong>可能仍然“动”，但一旦父级<strong>整体替换</strong>这个对象，你的快照<strong>感知不到</strong>。这会制造“有时动、有时不动”的错觉——最危险。</li></ul></li></ul><p><strong>保持响应的思路</strong>：</p><ol><li><strong>不要快照</strong>：优先让组合函数直接接收 props（保持只读、可追踪），以及单独接收需要写回的 model。</li><li><strong>按键传递“活的引用”</strong>：若只要几项，用“逐键引用”的方式（针对某个键做引用化）传给组合函数，而不是值的拷贝。</li><li><strong>统一“可写模型”路径</strong>：defineModel() 返回的是可写 ref，应当<strong>以它作为单一事实来源</strong>传入组合函数，而不是把 model.value拍平成普通值。</li><li><strong>明确语义</strong>：如果组合函数<strong>只</strong>需要初始值（不关心后续变更），那才用快照；否则一律传“活的引用”。</li></ol><p><strong>实践建议</strong>：</p><ul><li>读数据 → 传<strong>可追踪的只读来源</strong>（props 或逐键引用）。</li><li>写数据 → 传<strong>可写的模型引用</strong>（model），在组合函数里通过它“原子写回”。</li><li>避免把“读写语义”混在一次 ... 展开里，否则很容易一半失活、一半可写，埋下隐患。</li></ul><p>一句话结论：...props = <strong>静态快照</strong>；要响应式，就<strong>传活的源（props 本体 / 逐键引用 / 模型 ref）</strong>，把“写回”集中走 defineModel。</p></div>',1)])])}const _=s(p,[["render",n]]);export{c as __pageData,_ as default};
